"""Generate the Python/TypeScript parity fixture for the aspect-presence gate.

The backend's :mod:`app.services.aspect_match` decides whether a request is
refused with 422; ``frontend/src/lib/words.ts`` reimplements the same rule so
the UI can block before sending. Two implementations of one rule drift, and
the failure is invisible from either side alone -- the UI either rejects
something the server would have answered, or lets through something the
server refuses.

So the Python side writes down its answers here, and both test suites assert
against this file: ``backend/tests/test_stem_parity.py`` checks Python still
agrees with it, ``frontend/src/lib/words.parity.test.ts`` checks TypeScript
does. Python is the authority -- it is the one that returns the status code.

Regenerate (and read the diff carefully, it is a contract change):

    cd backend && python tests/fixtures/generate_stem_parity.py
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

BACKEND_ROOT = Path(__file__).resolve().parents[2]
if str(BACKEND_ROOT) not in sys.path:
    sys.path.insert(0, str(BACKEND_ROOT))

from app.services.aspect_match import aspect_in_text, stem  # noqa: E402

#: Words covering every branch of ``stem`` plus the cases that must *not* be
#: stemmed. Grouped only for reading; the fixture is a flat list.
WORDS: list[str] = [
    # plain
    "screen", "Screen", "SCREEN", "keyboard", "trackpad",
    # possessives, both apostrophes
    "screen's", "screen’s", "battery's", "OS's",
    # -ies
    "batteries", "memories", "ties", "dies",
    # -sses/-shes/-ches/-xes/-zes
    "glasses", "dishes", "watches", "boxes", "sizes", "buzzes",
    # plain -s
    "screens", "drives", "keys", "ports", "fans",
    # the length guards: not plurals
    "OS", "os", "bus", "this", "is", "us", "as", "gas", "lens",
    # no -ing/-ed rules
    "priced", "pricing", "cooling", "loaded", "used",
    # digits and hyphens
    "500GB", "wi-fi", "two-year", "i7", "3", "1080p",
    # accents and non-ASCII letters
    "café", "cafés", "naïve", "jalapeño", "jalapeños", "crème",
    # these two are where Python's casefold() and JS's toLowerCase() can part
    # company; the fixture records whatever Python does, and the TS test is
    # what reveals a disagreement.
    "Straße", "STRASSE", "İstanbul",
    # odd but legal input
    "", "...", "a", "ss", "s",
]

#: ``(text, aspect)`` pairs for ``aspect_in_text``: presence, contiguity,
#: whole-word matching, inflection, and the empty-needle case.
PAIRS: list[tuple[str, str]] = [
    ("The battery life is great but the screen is dim.", "screen"),
    ("The battery life is great but the screen is dim.", "SCREEN"),
    ("The battery life is great but the screen is dim.", "keyboard"),
    ("The battery life is great but the screen is dim.", "display"),
    ("The battery life is great but the screen is dim.", "batteries"),
    ("The battery life is great but the screen is dim.", "battery life"),
    ("The battery life is great but the screen is dim.", "the"),
    ("The battery life is great but the screen is dim.", ""),
    ("The battery life is great but the screen is dim.", "..."),
    ("a hard case and a test drive", "hard drive"),
    ("it has a hard drive", "hard drive"),
    ("it has two hard drives", "hard drive"),
    ("most of it is fine", "OS"),
    ("the OS is fine", "OS"),
    ("the screen's brightness is fine", "screen"),
    ("the screen’s brightness is fine", "screen"),
    ("It comes with a 500GB hard drive.", "500GB hard drive"),
    ("It comes with a 500GB hard drive.", "hard drive and"),
    ("the wi-fi keeps dropping", "wi-fi"),
    ("the wifi keeps dropping", "wi-fi"),
    ("the café was loud", "café"),
    ("the cafés were loud", "café"),
    ("the price is too high", "priced"),
    ("I was priced out", "price"),
    ("the glasses were dirty", "glass"),
    ("the box arrived dented", "boxes"),
    ("this is a bus", "bus"),
    ("the lens is scratched", "lens"),
    ("drive hard, hard drive", "hard drive"),
    ("the food and the service", "food and the service"),
]


def main() -> int:
    fixture = {
        "_comment": (
            "Generated by backend/tests/fixtures/generate_stem_parity.py. "
            "Python's app.services.aspect_match is the authority; "
            "frontend/src/lib/words.ts must agree. Do not edit by hand."
        ),
        "stems": [{"word": word, "stem": stem(word)} for word in WORDS],
        "presence": [
            {"text": text, "aspect": aspect, "present": aspect_in_text(text, aspect)}
            for text, aspect in PAIRS
        ],
    }
    out = Path(__file__).with_name("stem_parity.json")
    out.write_text(json.dumps(fixture, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"wrote {out} ({len(WORDS)} words, {len(PAIRS)} pairs)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
